# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİKDÖRTGENLER PRİZMASININ AÇINIMI VE YÜZEY ALANI</text>\n  <rect x="25" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Yüzey Açınımı (6 Dikdörtgensel Yüz)</text>\n  <rect x="135" y="85" width="60" height="32" fill="#93c5fd" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="165" y="105" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">Üst (a·b)</text>\n  <rect x="95" y="117" width="40" height="45" fill="#fde047" stroke="#ca8a04" stroke-width="1.5"/>\n  <text x="115" y="143" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#854d0e">Sol (b·c)</text>\n  <rect x="135" y="117" width="60" height="45" fill="#86efac" stroke="#15803d" stroke-width="1.5"/>\n  <text x="165" y="143" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">Ön (a·c)</text>\n  <rect x="195" y="117" width="40" height="45" fill="#fde047" stroke="#ca8a04" stroke-width="1.5"/>\n  <text x="215" y="143" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#854d0e">Sağ (b·c)</text>\n  <rect x="235" y="117" width="60" height="45" fill="#86efac" stroke="#15803d" stroke-width="1.5"/>\n  <text x="265" y="143" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">Arka (a·c)</text>\n  <rect x="135" y="162" width="60" height="32" fill="#93c5fd" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="165" y="182" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">Alt (a·b)</text>\n  <text x="185" y="218" text-anchor="middle" font-size="11" fill="#334155">Karşılıklı yüzler ikişer ikişer birbirine eşittir!</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yüzey Alanı Bağıntısı</text>\n  <text x="378" y="102" font-size="11.5" fill="#334155">• Ayrıt uzunlukları: <tspan font-weight="bold">a</tspan> (boy), <tspan font-weight="bold">b</tspan> (en), <tspan font-weight="bold">c</tspan> (yükseklik)</text>\n  <text x="378" y="128" font-size="11.5" fill="#334155">• Alt ve Üst Taban: 2 · (a · b)</text>\n  <text x="378" y="152" font-size="11.5" fill="#334155">• Ön ve Arka Yüz: 2 · (a · c)</text>\n  <text x="378" y="176" font-size="11.5" fill="#334155">• Sağ ve Sol Yan Yüz: 2 · (b · c)</text>\n  <rect x="378" y="190" width="278" height="36" rx="6" fill="#dcfce7" stroke="#16a34a"/>\n  <text x="517" y="213" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Yüzey Alanı = 2 · (a·b + a·c + b·c)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİRİM KÜPLERLE DİKDÖRTGENLER PRİZMASININ HACMİ</text>\n  <rect x="25" y="48" width="320" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Birim Küp Sayma Stratejisi</text>\n  <text x="45" y="102" font-size="11.5" fill="#334155">• Bir cismin boşlukta kapladığı yere <tspan font-weight="bold">hacim</tspan> denir.</text>\n  <text x="45" y="128" font-size="11.5" fill="#334155">• Ölçüt: Ayrıtı 1 birim olan <tspan font-weight="bold">birim küp (1 br³)</tspan>.</text>\n  <text x="45" y="154" font-size="11.5" fill="#334155">• 1. Katmandaki küp sayısı = Boy × En (a · b)</text>\n  <text x="45" y="180" font-size="11.5" fill="#334155">• Toplam katman sayısı = Yükseklik (c)</text>\n  <text x="185" y="214" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">Prizmanın içi boşluk kalmadan doldurulur!</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hacim Bağıntısı (MAT.7.4.4)</text>\n  <text x="380" y="104" font-size="11.5" fill="#334155">Örnek Prizma: a = 4 br, b = 3 br, c = 2 br</text>\n  <text x="380" y="130" font-size="11.5" fill="#334155">• Tabandaki 1 katmanda: 4 × 3 = 12 birim küp</text>\n  <text x="380" y="156" font-size="11.5" fill="#334155">• 2 katmanda toplam: 12 × 2 = 24 birim küp</text>\n  <rect x="378" y="176" width="278" height="48" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="517" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Hacim = Taban Alanı × Yükseklik</text>\n  <text x="517" y="215" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">V = (a · b) · c = a · b · c</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÖZEL PRİZMALAR: KARE PRİZMA VE KÜPÜN ALAN / HACİM ÖZETİ</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kare Prizma (Taban: a × a, Yükseklik: c)</text>\n  <text x="48" y="104" font-size="11.5" fill="#334155">• Alt ve üst tabanı birbirine eş iki <tspan font-weight="bold">kare</tspan>dir.</text>\n  <text x="48" y="130" font-size="11.5" fill="#334155">• Yan yüzleri birbirine eş 4 dikdörtgendir.</text>\n  <text x="48" y="160" font-size="11.5" font-weight="bold" fill="#166534">• Yüzey Alanı = 2·a² + 4·(a·c)</text>\n  <text x="48" y="188" font-size="11.5" font-weight="bold" fill="#166534">• Hacmi (V) = a · a · c = a² · c</text>\n  <text x="185" y="218" text-anchor="middle" font-size="11" fill="#334155">Dikdörtgenler prizmasının özel halidir.</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Küp (Tüm Ayrıtları Eşit: a × a × a)</text>\n  <text x="378" y="104" font-size="11.5" fill="#334155">• 6 yüzünün tamamı birbirine eş <tspan font-weight="bold">kare</tspan>dir.</text>\n  <text x="378" y="130" font-size="11.5" fill="#334155">• Bir yüzünün alanı = a · a = a²</text>\n  <text x="378" y="160" font-size="11.5" font-weight="bold" fill="#991b1b">• Yüzey Alanı = 6 · a²</text>\n  <text x="378" y="188" font-size="11.5" font-weight="bold" fill="#991b1b">• Hacmi (V) = a · a · a = a³</text>\n  <text x="515" y="218" text-anchor="middle" font-size="11" fill="#334155">12 eş ayrıtı ve 8 köşesi vardır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
